import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { PhoneOrEmailFields, PhoneOrEmailFieldsProps, createContactField } from "./phone-or-email-fields";
import { Form, FormField, useForm } from "@/core/helpers/form-builder";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

// The component needs a form-builder form holding both contact fields and a parent that owns the selected
// method, so the stories wrap it. The form is built once per mount from the field names in the args, and both
// callbacks are forwarded to the args (spies) so they still show up in the Actions panel.
const InteractivePhoneOrEmailFields = (props: PhoneOrEmailFieldsProps) => {
  const { t } = useTranslation();
  const [initialForm] = useState<Form>(() => {
    const phone = createContactField({ fieldType: "phone", name: props.phoneFieldName, t });
    const email = createContactField({ fieldType: "email", name: props.emailFieldName, t });
    return {
      fields: new Map<string, FormField>([
        [phone.name, phone.field],
        [email.name, email.field],
      ]),
    };
  });
  const [form, , handleFieldOnChange] = useForm(initialForm, true);
  const [method, setMethod] = useState(props.method);
  return (
    <PhoneOrEmailFields
      {...props}
      form={form}
      method={method}
      onMethodChange={(name, newMethod) => {
        setMethod(newMethod);
        props.onMethodChange?.(name, newMethod);
      }}
      onContactChange={(name, value) => {
        handleFieldOnChange(name, value);
        props.onContactChange(name, value);
      }}
    />
  );
};

const meta = {
  title: "Primitives/Form Fields/Phone Or Email Fields",
  component: PhoneOrEmailFields,
  parameters: {
    docs: {
      description: {
        component:
          "Contact section that lets the user pick phone or e-mail in a `StyledRadioButtons` group and shows one " +
          "`InputField` for the chosen method. Both fields live in a form-builder `Form` owned by the parent; " +
          "create them with `createContactField`, which sets label, validation type, input mode, autocomplete " +
          "and error text per method. The component flips `isRequired` and `validationType` on the two fields so " +
          "only the visible one is validated. The parent also owns `method` and updates it from " +
          "`onMethodChange`, and gets every keystroke of the visible field through `onContactChange`. The label " +
          "props are translation keys, not text.",
      },
    },
  },
  argTypes: {
    radioGroupLabel: { table: { disable: true } },
    radioLabelPhone: { table: { disable: true } },
    radioLabelEmail: { table: { disable: true } },
    form: { table: { disable: true } },
    radioGroupName: { table: { disable: true } },
    phoneFieldName: { table: { disable: true } },
    emailFieldName: { table: { disable: true } },
    onMethodChange: { table: { disable: true } },
    onContactChange: { table: { disable: true } },
    onKeyDown: { table: { disable: true } },
  },
  args: {
    // The wrapper builds the real form from the field names below; this only satisfies the required prop.
    form: { fields: new Map<string, FormField>() },
    radioGroupName: "deliveryMethod",
    radioGroupLabel: "phoneOrEmailFieldsRadioGroupLabel",
    radioLabelPhone: "phone",
    radioLabelEmail: "email",
    method: "phone",
    phoneFieldName: "phoneNumber",
    emailFieldName: "emailAddress",
    reverseOptions: false,
    onMethodChange: fn(),
    onContactChange: fn(),
    onKeyDown: fn(),
  },
  render: (args) => <InteractivePhoneOrEmailFields {...args} />,
} satisfies Meta<typeof PhoneOrEmailFields>;

export default meta;

type Story = StoryObj<typeof meta>;

