/** The form-builder validates the phone field about a second after typing stops, so the story ends on the
 * phone validation error. */
export const InvalidPhoneError: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // The required marker is an inline span, so the accessible name is "Telefonnummer(Obligatoriskt)".
    const input = canvas.getByRole("textbox", { name: /^Telefonnummer/ });
    await userEvent.type(input, "12");
    await waitFor(() => expect(canvas.getByText("Vänligen ange ett giltigt telefonnummer")).toBeVisible(), {
      timeout: 3000,
    });
    await expect(input).toHaveAttribute("aria-invalid", "true");
  },
};

const onMethodChangeSpy = fn();

export const TestSwitchMethod: Story = {
  args: { onMethodChange: onMethodChangeSpy },
  // Behaviour only: picking the other radio swaps the input field and reports the new method.
  play: async ({ canvasElement }) => {
    onMethodChangeSpy.mockClear();
    const canvas = within(canvasElement);
    await expect(canvas.getByRole("textbox", { name: /^Telefonnummer/ })).toBeVisible();
    // Match the option label as a suffix so a marker appended to the accessible name does not break the query.
    await userEvent.click(canvas.getByRole("radio", { name: /E-post$/ }));
    await expect(onMethodChangeSpy).toHaveBeenCalledWith("deliveryMethod", "email");
    await expect(canvas.getByRole("textbox", { name: /^E-post/ })).toBeVisible();
    await expect(canvas.queryByRole("textbox", { name: /^Telefonnummer/ })).not.toBeInTheDocument();
  },
};
